#!name=财新网
#!desc=某些APP要清除缓存或者重新安装拦截广告才会生效！
#!author=奶思
#!homepage=https://github.com/fmz200/wool_scripts
#!icon=https://raw.githubusercontent.com/fmz200/wool_scripts/main/icons/gif/naisi-01.gif
#!raw-url=https://github.com/fmz200/wool_scripts/raw/main/Loon/plugin/split/partC/Caixin.lpx
#!tg-channel=https://t.me/inaisi
#!date=2026-11-11 21:17:23
#############################################


[Argument]
cdxb_enable = switch,true,false,tag=财新-脚本开关

[Rule]
DOMAIN-SUFFIX, apollo.caixin.com, REJECT
DOMAIN-SUFFIX, logstat.caixin.com, REJECT
DOMAIN-SUFFIX, promote.caixin.com, REJECT


[Script]
response if ${url} ~= /^https?:\/\/gg\.caixin\.com\/s\?z=caixin&op=1&c=3362/i then script("https://raw.githubusercontent.com/fmz200/wool_scripts/main/Scripts/caixin/caixinAd.js") with enable=${cdxb_enable}, tag="财新广告", timeout=60, requires_body=true

[MITM]
hostname = gg.caixin.com
